.header-nav-main.nav .nav-dropdown li .sub-menu{

    color: #fff;
    top: 55px;
    min-width: 200px;
    left: 0;
    position: absolute;
    visibility: hidden;
    opacity: 0;
    transition: all 0.25s;
    -moz-transition: all 0.25s;
    -webkit-transition: all 0.25s;
    z-index: 111;
    position: absolute;

    top: -10px;
    left: 120%;

}
.header-nav-main.nav .nav-dropdown li:hover .sub-menu{
    left: 100%;
    opacity: 1;
    visibility: visible;
}
