  .hal {
      position: fixed;
      left: 10px;
      bottom: 12px;
      width: 90px;
      z-index: 9999;

    }

    @keyframes fadeleft {
      from {
        opacity: 0;
        left: -150px;
      }

      to {
        opacity: 1;
        left: 10px;
      }
    }

    .halitem {
      position: relative;
      visibility: visible;
      background-color: transparent;
      width: 70px;
      height: 70px;
      cursor: pointer;
      z-index: 9999;
      -webkit-backface-visibility: hidden;
      -webkit-transform: translateZ(0);
      transition: visibility .5s;
      left: 0px;
      bottom: 25px;
      display: block;
    }

    .halbg {
      width: 60px;
      height: 60px;
      top: 25px;
      left: 2px;
      position: absolute;
      box-shadow: 0 0 0 0;
      border-radius: 50%;
      border: 2px solid transparent;

      transition: all .5s;
      -webkit-transform-origin: 50% 50%;
      -ms-transform-origin: 50% 50%;
      transform-origin: 50% 50%;
    }

    .animation1 {
      -webkit-animation: zigzag 2.3s infinite ease-in-out;
      animation: zigzag 2.3s infinite ease-in-out;
      -webkit-animuiion: zoom 1.3s infinite;
      animation: zoom 1.3s infinite;
    }

    .animation2 {
      -webkit-animation: zigzag 2s infinite ease-in-out;
      animation: zigzag 2s infinite ease-in-out;
    }

    .halimg {
      width: 40px;
      height: 40px;
      line-height: 40px;
      top: 33px;
      left: 12px;
      position: absolute;
      border-radius: 50%;
      display: flex;
      justify-content: center;
    }

    .halimg a {
      display: block;
    }

  .halcontent {
      color: #fff;
      padding: 10px 15px;
      border-radius: 99px;
      position: absolute;
      z-index: 0;
      top: 32px;
      transition-duration: 2s;
      display: initial;
      margin-left: 7px;
      font-size: 100%;
      width: 165px;
      text-align: right;
      transition-duration: 2s;
      box-shadow: 0 0 0 0 #cb9541 ;
  }

    .halitem:hover .halcontent {
      display: block;
    }

    .halmobile {
      position: fixed !important;
      right: 0px;
      bottom: 0px;
      width: 100%;
      z-index: 99999 !important;
    }

    .mobileicon {
      float: left;
      text-align: center;
      padding: 5px 0;
      position: relative;
      z-index: 99999 !important;
      border-right: 1px solid #fff;
    }

    .mobileicon img {
      width: 30px;
    }

    .mobileicon p {
      margin-bottom: 0;
    }

    .mobileicon a {
      color: #fff;
    }

    .mobileicon img {
      justify-content: center;
      -webkit-animation: zigzag 2s infinite ease-in-out;
      animation: zigzag 2s infinite ease-in-out;
    }

    @-webkit-keyframes zigzag {
      0% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
      }

      10% {
        -webkit-transform: rotate(-25deg) scale(1) skew(1deg);
      }

      20% {
        -webkit-transform: rotate(25deg) scale(1) skew(1deg);
      }

      30% {
        -webkit-transform: rotate(-25deg) scale(1) skew(1deg);
      }

      40% {
        -webkit-transform: rotate(25deg) scale(1) skew(1deg);
      }

      50% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
      }

      100% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
      }
    }

    @keyframes zigzag {
      0% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
      }

      10% {
        -webkit-transform: rotate(-25deg) scale(1) skew(1deg);
      }

      20% {
        -webkit-transform: rotate(25deg) scale(1) skew(1deg);
      }

      30% {
        -webkit-transform: rotate(-25deg) scale(1) skew(1deg);
      }

      40% {
        -webkit-transform: rotate(25deg) scale(1) skew(1deg);
      }

      50% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
      }

      100% {
        -webkit-transform: rotate(0) scale(1) skew(1deg);
      }
    }

    @-webkit-keyframes zoom {
      0% {
        transform: scale(.9)
      }

      70% {
        transform: scale(1);
        box-shadow: 0 0 0 15px transparent
      }

      100% {
        transform: scale(.9);
        box-shadow: 0 0 0 0 transparent
      }
    }

    @keyframes zoom {
      0% {
        transform: scale(.9)
      }

      70% {
        transform: scale(1);
        box-shadow: 0 0 0 15px transparent
      }

      100% {
        transform: scale(.9);
        box-shadow: 0 0 0 0 transparent
      }
    }
